mkdir -p src/db && 
cat > src/db/schema.ts <<'EOF'
import { date, pgTable, serial, text } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  createdAt: date("created_at", { mode: "string" }).notNull().defaultNow(),
});
EOF
cat > src/db/index.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

const globalForDb = globalThis as unknown as { pg?: ReturnType<typeof postgres> };

function connect() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");
  return postgres(url);
}

// Reuse the client across Next.js dev hot reloads.
const client = (globalForDb.pg ??= connect());

export const db = drizzle(client, { schema });
EOF
cat > src/db/migrate.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await migrate(drizzle(client), { migrationsFolder: "./drizzle" });
await client.end();
console.log("Migrations applied");
EOF
cat > src/db/seed.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { users } from "./schema";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await drizzle(client)
  .insert(users)
  .values([
    { email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ])
  .onConflictDoNothing({ target: users.email });
await client.end();
console.log("Seeded");
EOF
cat > drizzle.config.ts <<'EOF'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL ?? "" },
});
EOF
cat > src/lib/users.ts <<'EOF'
import { asc, eq } from "drizzle-orm";
import { db } from "@/db";
import { users } from "@/db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: typeof users.$inferSelect): User {
  return { ...row, id: String(row.id) };
}

export async function listUsers(): Promise<User[]> {
  const rows = await db.select().from(users).orderBy(asc(users.id));
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  if (!/^\d+$/.test(id)) return undefined;
  const [row] = await db.select().from(users).where(eq(users.id, Number(id)));
  return row && toUser(row);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const [row] = await db.select().from(users).orderBy(asc(users.id)).limit(1);
  return row && toUser(row);
}
EOF
